@media(prefers-reduced-motion:reduce){.rel,.rel i{transition:none}}
/* docs execution graph */
.gtop{display:flex;justify-content:space-between;align-items:flex-end;gap:12px 20px;flex-wrap:wrap;margin-bottom:16px}
.gtop h2{margin-bottom:0}
.seg{display:inline-flex;padding:3px;border-radius:12px;background:rgba(29,29,31,.06)}
.seg button{background:transparent;color:var(--muted);border-radius:9px;padding:6px 14px;min-height:36px;font-size:14px}
.seg button:hover{background:transparent;color:var(--ink)}
.seg button[aria-pressed="true"]{background:var(--surface);color:var(--ink);box-shadow:0 1px 3px rgba(0,0,0,.1)}
.gwrap{display:grid;grid-template-columns:minmax(0,1fr) 320px;gap:20px;align-items:start}
.gwrap.wide{grid-template-columns:minmax(0,1fr)}
.gwrap.wide .gpan{display:none}
.gkey{display:flex;flex-wrap:wrap;gap:6px 16px;font-size:13px;color:var(--muted);margin:0 0 14px}
.gkey span{display:inline-flex;align-items:center;gap:6px}
.gkey i{width:10px;height:10px;border-radius:50%;display:inline-block}
.graph{list-style:none;padding:20px 16px 20px 20px;position:relative}
.graph>li{position:relative;padding-left:34px}
.graph>li::before{content:"";position:absolute;left:9px;top:0;bottom:0;width:2px;background:#DCDCE0}
.graph>li:first-child::before{top:22px}
.graph>li:last-child::before{bottom:auto;height:22px}
.gb{all:unset;box-sizing:border-box;display:grid;grid-template-columns:minmax(0,1fr) auto;gap:2px 12px;width:100%;padding:10px 12px;border-radius:12px;cursor:pointer;position:relative;min-height:44px}
.gb:hover{background:rgba(29,29,31,.04)}
.gb[aria-pressed="true"]{background:rgba(0,102,204,.07);box-shadow:inset 0 0 0 1px rgba(0,102,204,.25)}
.gb:focus-visible{outline:3px solid var(--accent);outline-offset:2px}
.gd{position:absolute;left:-34px;top:13px;width:20px;height:20px;border-radius:50%;display:grid;place-items:center;font:700 11px/1 "Geist Mono",ui-monospace,Consolas,monospace;color:#fff;background:#C7C7CC;box-shadow:0 0 0 4px var(--surface)}
.gs{font-size:12px;font-weight:600;color:var(--muted);letter-spacing:.01em}
