/* docs execution graph */
var KIND={docs_bug:["Docs are wrong","k-docs","n-docs"],environment:["Missing prerequisite","k-env","n-env"],product_bug:["Product bug","k-other","n-fail"],needs_secret:["Needs a secret","k-other","n-block"]};
var EVK={trace:"neatlogs trace",checkpoint:"Entire checkpoint",session:"Entire session",trail:"Entire Trail",pr:"Pull request",comment:"Evidence comment"};
var G=null;
function errLine(t){
  var L=String(t||"").split("\n").map(function(x){return x.trim()}).filter(Boolean);
  for(var i=L.length-1;i>=0;i--)if(/error|not found|no such|denied|failed|cannot|unable/i.test(L[i]))return L[i];
  return L.length?L[L.length-1]:"";
}
function stepKind(d,s){
  var p=(d.patches||[]).filter(function(x){return x.step_id===s.id});
  if(p.length)return p[p.length-1].failure_class;
  var g=(d.gave_up||[]).filter(function(x){return x&&x.step_id===s.id&&x.failure_class});
  if(g.length)return g[0].failure_class;
  var c=d.classifications&&d.classifications[String(s.id)];
  if(c&&c.probabilities){var top=null;Object.keys(c.probabilities).forEach(function(k){if(top===null||c.probabilities[k]>c.probabilities[top])top=k});return top}
  return null;
}
function tries(s){
  if(Array.isArray(s.tries)&&s.tries.length)return s.tries;
  if(s.exit_code==null)return [];
  return [{command:s.command,exit_code:s.exit_code,passed:s.status==="passed"}];
}
function nodeOf(d,s){
  var t=tries(s),failedOnce=t.some(function(x){return !x.passed})||(s.attempts>1),k=stepKind(d,s),K=KIND[k]||null;
  var n={s:s,kind:k,K:K,tries:t,patches:(d.patches||[]).filter(function(x){return x.step_id===s.id})};
  var st=s.status||"pending";
  if(st==="skipped"){n.cls="n-skip";n.label="Not run: out of scope";n.glyph="-"}
  else if(st==="pending"){n.cls="n-none";n.label="Not run";n.glyph=""}
  else if(st==="needs_human"||k==="needs_secret"&&st!=="passed"){n.cls="n-block";n.label="Blocked";n.glyph="!"}
  else if(st==="passed"&&!failedOnce){n.cls="n-pass";n.label="Passed";n.glyph="✓"}
  else if(st==="passed"){n.cls=K?K[2]:"n-fail";n.label="Failed as written";n.glyph="✗";n.fixed=true}
  else{n.cls=K?K[2]:"n-fail";n.label=st==="gave_up"?"Failed, gave up":"Failed";n.glyph="✗"}
  return n;
}
function evFor(d,id){return (d.evidence||[]).filter(function(e){return e&&e.step_id===id})}
function linkTo(e,text){
  if(e.url&&safeUrl(e.url)){var a=el("a",null,text||e.label||EVK[e.kind]||e.url);a.href=e.url;a.target="_blank";a.rel="noopener noreferrer";return a}
