  sv.forEach(function(c,k){svg.appendChild(E("path",{d:c.map(function(v,i){return(i?"L":"M")+X(i).toFixed(1)+" "+Y(v).toFixed(1)}).join(""),"class":"ln",stroke:col[k]}))});
  var ends=sv.map(function(c,k){return{k:k,y:Y(c[N-1])}}).sort(function(a,b){return a.y-b.y});
  for(var j=1;j<ends.length;j++)if(ends[j].y-ends[j-1].y<16)ends[j].y=ends[j-1].y+16;
  ends.forEach(function(e){var c=sv[e.k];svg.appendChild(E("circle",{cx:X(N-1),cy:Y(c[N-1]),r:4,fill:col[e.k],stroke:"#fff","stroke-width":2}));
   svg.appendChild(E("text",{x:X(N-1)+10,y:e.y+4,"class":"el"},usd(c[N-1])))});
  var zi=sv[1].findIndex(function(v){return v<0});
  if(zi>0){svg.appendChild(E("circle",{cx:X(zi),cy:Y(sv[1][zi]),r:5,fill:col[1],stroke:"#fff","stroke-width":2}));
