.pj li{counter-increment:pj;border-radius:20px;padding:18px 18px 16px;display:flex;flex-direction:column;gap:6px;min-width:0}
.pj .k{font:600 11px/1 "Geist Mono",ui-monospace,monospace;letter-spacing:.06em;text-transform:uppercase;color:var(--accent)}
.pj .k::before{content:counter(pj) "  "}
.pj b{font-size:17px;letter-spacing:-.02em;line-height:1.25}
.pj p{font-size:14px;line-height:1.45;color:var(--muted);margin:0}
.pj p code{font-size:12.5px}
.pj a{margin-top:auto;padding-top:4px;font-size:14px;font-weight:600}
.pj li.hot b{color:var(--bad)}
.pc2{margin-top:16px;border-radius:24px;padding:22px 22px 16px}
.pc2 h3{font-size:17px;letter-spacing:-.02em}
.pc2 .sub{font-size:13.5px;color:var(--muted);margin-top:2px}
.lgd2{display:flex;flex-wrap:wrap;gap:6px 18px;margin:14px 0 4px;font-size:13.5px;color:var(--ink)}
.lgd2 span{display:inline-flex;align-items:center;gap:7px}
.lgd2 i{width:16px;height:2px;border-radius:2px;display:inline-block}
.cw{position:relative}
.cw svg{display:block;width:100%;height:auto;overflow:visible;touch-action:pan-y}
.cw .gr{stroke:rgba(29,29,31,.08);stroke-width:1}
.cw .z{stroke:rgba(29,29,31,.35);stroke-width:1}
.cw .ax{font:11.5px "Geist Mono",ui-monospace,monospace;fill:var(--muted)}
.cw .ln{fill:none;stroke-width:2;stroke-linejoin:round;stroke-linecap:round}
.cw .el,.cw .an{font:600 12px Geist,-apple-system,"Segoe UI",sans-serif;fill:var(--ink)}
.cw .ch{stroke:rgba(29,29,31,.25);stroke-width:1}
.cw .tip{position:absolute;top:0;pointer-events:none;background:#fff;border-radius:12px;box-shadow:0 0 0 1px var(--hair),0 8px 24px -8px rgba(30,50,110,.25);padding:10px 12px;font-size:13px;line-height:1.5;min-width:200px;opacity:0;transition:opacity .15s}
.cw .tip b{display:block;font-size:12px;color:var(--muted);font-weight:600}
.cw .tip div{display:flex;align-items:center;gap:12px;justify-content:space-between}
.cw .tip em{font-style:normal}
.cw .tip i{width:10px;height:2px;display:inline-block;margin-right:6px;vertical-align:middle}
.cw .tip span{font-family:"Geist Mono",ui-monospace,monospace}
.pc2 details{margin-top:8px;font-size:13.5px}
.pc2 summary{cursor:pointer;font-weight:600;color:var(--accent);min-height:36px;display:flex;align-items:center}
.pc2 table{width:100%;border-collapse:collapse;font-size:13px;margin-top:6px}
.pc2 th,.pc2 td{padding:5px 8px;text-align:right;border-bottom:1px solid var(--hair);font-variant-numeric:tabular-nums;white-space:nowrap}
.pc2 th:first-child,.pc2 td:first-child{text-align:left}
.pc2 .tw{overflow-x:auto}
.fx2{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;margin-top:12px}
.fx2 div{border-radius:20px;padding:16px 18px}
.fx2 b{display:block;font-size:16px;letter-spacing:-.02em}
.fx2 span{font-size:14px;color:var(--muted)}
.pl-note{margin-top:12px;font-size:13px;color:var(--muted)}
@media(max-width:820px){.pj{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media(max-width:520px){.pj,.fx2{grid-template-columns:minmax(0,1fr)}.pc2{padding:18px 14px 12px}}
"""
